-- Fresh database snapshot at version 20. Flyway uses B migrations only on an empty database.
-- Existing installations continue through their V migrations; do not edit applied migrations.
-- Entity schema plus the constraints, defaults, and indexes introduced by V1-V20.

create table activities (
    units integer,
    id bigint generated by default as identity,
    timestamp timestamp(6),
    user_id bigint,
    city varchar(255),
    description varchar(255),
    project_name varchar(255),
    type varchar(255),
    user_name varchar(255),
    primary key (id)
);

create table areas (
    active boolean not null,
    subscription_rate float(53),
    created_at timestamp(6),
    id bigint generated by default as identity,
    city varchar(100) not null,
    name varchar(100) not null,
    state varchar(100) not null,
    primary key (id),
    unique (name, city, state)
);

create table broker_locations (
    broker_id bigint,
    id bigint generated by default as identity,
    location_id bigint,
    primary key (id)
);

create table buildings (
    total_floors integer not null,
    created_at timestamp(6),
    id bigint generated by default as identity,
    project_id bigint not null,
    updated_at timestamp(6),
    building_type varchar(50),
    tower_code varchar(50),
    name varchar(120) not null,
    description TEXT,
    primary key (id)
);

create table conversation_participants (
    joined_at timestamp(6),
    last_read_at timestamp(6),
    user_id bigint not null,
    conversation_id uuid not null,
    primary key (user_id, conversation_id)
);

create table conversations (
    created_at timestamp(6),
    updated_at timestamp(6),
    id uuid not null,
    name varchar(255),
    type varchar(255),
    primary key (id)
);

create table custom_cities (
    active boolean not null,
    subscription_rate float(53),
    added_at timestamp(6),
    added_by bigint,
    id bigint generated by default as identity,
    city varchar(255) not null,
    state varchar(255) not null,
    primary key (id),
    unique (state, city)
);

create table employees (
    admin_id bigint,
    id bigint generated by default as identity,
    user_id bigint,
    email varchar(255),
    employee_id varchar(255) unique,
    name varchar(255),
    phone varchar(255),
    primary key (id)
);

create table floors (
    floor_number integer not null,
    total_units integer,
    building_id bigint not null,
    created_at timestamp(6),
    id bigint generated by default as identity,
    project_id bigint not null,
    updated_at timestamp(6),
    floor_type varchar(50) not null,
    floor_name varchar(100) not null,
    primary key (id),
    constraint uk_building_floor unique (building_id, floor_number)
);

create table follow_ups (
    is_completed boolean not null,
    completed_at timestamp(6),
    created_at timestamp(6),
    created_by_user_id bigint not null,
    deleted_at timestamp(6),
    id bigint generated by default as identity,
    lead_id bigint not null,
    owner_user_id bigint not null,
    scheduled_at timestamp(6) not null,
    updated_at timestamp(6),
    calling_type varchar(255) not null check ((calling_type in ('FIRST_CALL','FOLLOW_UP','SITE_VISIT','CLOSURE','NOT_INTERESTED'))),
    completion_note varchar(255),
    customer_name varchar(255) not null,
    description varchar(255),
    primary key (id)
);

create table leads (
    area_id bigint,
    assigned_user_id bigint,
    config_id bigint,
    id bigint generated by default as identity,
    project_id bigint,
    assigned_employee_id varchar(255),
    city varchar(255),
    customer_name varchar(255),
    email varchar(255),
    phone varchar(255),
    property_interest varchar(255),
    status varchar(255) check ((status in ('NEW','CONTACTED','INTERESTED','CLOSED'))),
    primary key (id)
);

create table locations (
    subscription_rate float(53),
    created_at timestamp(6),
    id bigint generated by default as identity,
    area varchar(255),
    city varchar(255),
    location_name varchar(255),
    state varchar(255),
    primary key (id)
);

create table message_reactions (
    reacted_at timestamp(6),
    user_id bigint not null,
    emoji varchar(10) not null,
    message_id uuid not null,
    primary key (message_id, user_id)
);

create table message_reads (
    read_at timestamp(6),
    user_id bigint not null,
    message_id uuid not null,
    primary key (user_id, message_id)
);

create table messages (
    created_at timestamp(6),
    edited_at timestamp(6),
    file_size bigint,
    sender_id bigint not null,
    conversation_id uuid not null,
    id uuid not null,
    reply_to_id uuid,
    content TEXT,
    file_mime_type varchar(255),
    file_name varchar(255),
    file_url varchar(255),
    type varchar(255),
    primary key (id)
);

create table otp_records (
    attempts integer,
    is_used boolean,
    created_at timestamp(6),
    expires_at timestamp(6) not null,
    id bigint generated by default as identity,
    otp_hash varchar(120) not null,
    email varchar(255) not null,
    purpose varchar(255) not null,
    primary key (id)
);

create table payments (
    subscription_rate float(53),
    amount_in_paise bigint,
    created_at timestamp(6) not null,
    id bigint generated by default as identity,
    renewal_applied_at timestamp(6),
    sub_admin_id bigint,
    verified_at timestamp(6),
    assigned_area varchar(255),
    assigned_city varchar(255),
    assigned_state varchar(255),
    currency varchar(255),
    plan_type varchar(255),
    razorpay_order_id varchar(255) unique,
    razorpay_payment_id varchar(255),
    razorpay_signature varchar(255),
    status varchar(255),
    primary key (id)
);

create table plans (
    duration_days integer,
    price float(53),
    id bigint generated by default as identity,
    name varchar(255),
    primary key (id)
);

create table project_configs (
    carpet_area_sqft float(53),
    completion_percentage integer not null,
    parking_available boolean,
    parking_cost float(53),
    price float(53) not null,
    rate_per_sqft float(53),
    saleable_area_sqft float(53),
    units integer not null,
    units_sold integer not null,
    id bigint generated by default as identity,
    project_id bigint not null,
    config_label varchar(255),
    flat_type varchar(255),
    floor_no varchar(255),
    listing_type varchar(255),
    property_type varchar(255),
    primary key (id)
);

create table project_documents (
    building_id bigint,
    config_id bigint,
    file_size bigint,
    id bigint generated by default as identity,
    project_id bigint,
    uploaded_at timestamp(6),
    uploaded_by bigint,
    document_category varchar(255),
    document_level varchar(255),
    file_name varchar(255),
    file_path varchar(255),
    file_type varchar(255),
    primary key (id)
);

create table project_units (
    config_id bigint not null,
    id bigint generated by default as identity,
    project_id bigint not null,
    sale_id bigint,
    sold_at timestamp(6),
    status varchar(20) not null,
    floor_no varchar(80),
    unit_no varchar(80),
    unit_label varchar(120) not null,
    primary key (id),
    constraint uk_project_unit_label unique (config_id, unit_label)
);

create table projects (
    built_up_area float(53),
    carpet_area float(53),
    has_multiple_towers boolean,
    is_deleted boolean not null,
    latitude float(53),
    longitude float(53),
    possession_date date,
    price float(53),
    price_per_sq_ft float(53),
    super_built_up_area float(53),
    total_built_up_area float(53),
    total_land_area float(53),
    tower_count integer,
    completed_at timestamp(6),
    created_at timestamp(6),
    deleted_at timestamp(6),
    id bigint generated by default as identity,
    location_id bigint,
    modified_by bigint,
    updated_at timestamp(6),
    uploaded_by bigint,
    address varchar(255),
    apartment_name varchar(255),
    area varchar(255),
    builder_email varchar(255),
    builder_name varchar(255),
    builder_number varchar(255),
    city varchar(255),
    cover_photo_url varchar(255),
    description TEXT,
    google_maps_url TEXT,
    ownership_type varchar(255),
    plot_dimensions varchar(255),
    plot_number varchar(255),
    project_name varchar(255),
    project_status varchar(255),
    property_category varchar(255),
    property_code varchar(255),
    property_subcategory varchar(255),
    property_type varchar(255),
    state varchar(255),
    status varchar(255),
    survey_number varchar(255),
    total_land_area_unit varchar(255),
    zip_code varchar(255),
    primary key (id)
);

create table property_units (
    balconies integer,
    bathrooms integer,
    bedrooms integer,
    built_up_area float(53),
    carpet_area float(53),
    parking_spaces integer,
    price float(53),
    rent_price float(53),
    super_built_up_area float(53),
    building_id bigint not null,
    created_at timestamp(6),
    floor_id bigint not null,
    id bigint generated by default as identity,
    property_project_id bigint not null,
    updated_at timestamp(6),
    built_up_area_unit varchar(20),
    carpet_area_unit varchar(20),
    status varchar(30) not null,
    facing varchar(50),
    owner_phone varchar(50),
    sub_type varchar(50),
    unit_type varchar(50) not null,
    unit_number varchar(80) not null,
    owner_email varchar(150),
    owner_name varchar(150),
    cover_image_url varchar(700),
    floor_plan_url varchar(700),
    description TEXT,
    primary key (id),
    constraint uk_floor_unit_number unique (floor_id, unit_number)
);

create table sales (
    amount float(53),
    carpet_area_sqft float(53),
    completion_percentage float(53),
    parking_available boolean,
    parking_cost float(53),
    rate_per_sqft float(53),
    saleable_area_sqft float(53),
    units_sold integer,
    configuration_id bigint,
    id bigint generated by default as identity,
    project_id bigint,
    sale_date timestamp(6),
    sold_by_user_id bigint,
    unit_id bigint,
    notes varchar(2000),
    buyer_email varchar(255),
    buyer_name varchar(255),
    buyer_phone varchar(255),
    config_label varchar(255),
    employee_id varchar(255),
    floor_no varchar(255),
    listing_type varchar(255),
    project_name varchar(255),
    property_type varchar(255),
    sold_by_name varchar(255),
    sold_by_role varchar(255),
    unit_label varchar(255),
    unit_no varchar(255),
    primary key (id)
);

create table subscriptions (
    end_date date,
    price float(53),
    start_date date,
    id bigint generated by default as identity,
    plan_id bigint,
    user_id bigint,
    plan_type varchar(255) check ((plan_type in ('ALL','CUSTOM'))),
    status varchar(255),
    primary key (id)
);

create table temp_registrations (
    subscription_amount numeric(10,2) not null,
    completed_at timestamp(6),
    created_at timestamp(6),
    expires_at timestamp(6),
    id uuid not null,
    registration_token uuid not null,
    aadhaar_number varchar(20),
    pan_number varchar(20),
    phone varchar(20),
    status varchar(20) not null,
    plan_type varchar(30) not null,
    area varchar(100),
    city varchar(100),
    name varchar(100) not null,
    razorpay_order_id varchar(100) not null unique,
    razorpay_payment_id varchar(100),
    state varchar(100),
    email varchar(150) not null,
    aadhaar_card_url varchar(512),
    profile_photo_url varchar(512),
    selected_location_ids varchar(1000),
    failure_reason varchar(255),
    password_hash varchar(255) not null,
    razorpay_signature varchar(255),
    primary key (id)
);

create table unit_documents (
    version integer,
    building_id bigint not null,
    created_at timestamp(6),
    file_size bigint,
    floor_id bigint not null,
    id bigint generated by default as identity,
    property_project_id bigint not null,
    unit_id bigint not null,
    updated_at timestamp(6),
    uploaded_by bigint,
    document_type varchar(80) not null,
    content_type varchar(120),
    file_path varchar(700) not null,
    object_key varchar(700) not null,
    description TEXT,
    document_name varchar(255) not null,
    primary key (id)
);

create table user_kyc_documents (
    file_size bigint,
    id bigint generated by default as identity,
    updated_at timestamp(6),
    uploaded_at timestamp(6),
    user_id bigint,
    temp_registration_id uuid,
    verification_status varchar(20) not null check ((verification_status in ('PENDING','VERIFIED','REJECTED'))),
    document_type varchar(40) not null check ((document_type in ('PROFILE_PHOTO','AADHAAR_CARD','AADHAAR_FRONT','AADHAAR_BACK','PAN_CARD'))),
    content_type varchar(120) not null,
    object_key varchar(700) not null,
    original_file_name varchar(255),
    primary key (id)
);

create table users (
    amount_paid float(53),
    auto_renewal boolean,
    is_online boolean,
    subscription_expires_at date,
    subscription_rate float(53),
    subscription_start_at date,
    added_by bigint,
    area_id bigint,
    created_at timestamp(6),
    custom_city_id bigint,
    id bigint generated by default as identity,
    kyc_verified_at timestamp(6),
    kyc_verified_by bigint,
    last_login_at timestamp(6),
    last_seen timestamp(6),
    password_changed_at timestamp(6),
    token_version bigint,
    updated_at timestamp(6),
    aadhaar_card_url varchar(255),
    aadhaar_number varchar(255),
    assigned_area varchar(255),
    assigned_city varchar(255),
    assigned_state varchar(255),
    email varchar(255) unique,
    fcm_token varchar(255),
    kyc_rejection_reason varchar(255),
    kyc_status varchar(255),
    name varchar(255),
    pan_number varchar(255),
    password varchar(255),
    payment_method varchar(255),
    phone varchar(255),
    profile_photo_url varchar(255),
    razorpay_payment_id varchar(255),
    role varchar(255) check ((role in ('SUPER_ADMIN','ADMIN','SUB_ADMIN','EMPLOYEE'))),
    signup_source varchar(255),
    subscription_type varchar(255),
    primary key (id)
);

create index idx_buildings_project on buildings (project_id);

create index idx_floors_building on floors (building_id);

create index idx_floors_project on floors (project_id);

create index idx_project_unit_project on project_units (project_id);

create index idx_project_unit_config on project_units (config_id);

create index idx_project_unit_status on project_units (status);

create index idx_units_project on property_units (property_project_id);

create index idx_units_building on property_units (building_id);

create index idx_units_floor on property_units (floor_id);

create index idx_units_status on property_units (status);

create index idx_units_type on property_units (unit_type);

create index idx_temp_reg_expires on temp_registrations (expires_at, status);

create index idx_temp_reg_order on temp_registrations (razorpay_order_id);

create index idx_temp_reg_email_status on temp_registrations (email, status);

create index idx_unit_docs_unit on unit_documents (unit_id);

create index idx_unit_docs_project on unit_documents (property_project_id);

create index idx_kyc_doc_user on user_kyc_documents (user_id);

create index idx_kyc_doc_temp on user_kyc_documents (temp_registration_id);

create index idx_kyc_doc_type on user_kyc_documents (document_type);

alter table if exists conversation_participants add constraint FK84npv3fo2vwl7ut63im0p417q foreign key (conversation_id) references conversations;

alter table if exists conversation_participants add constraint FKjukjgq6uinvvk4307y8u9lixu foreign key (user_id) references users on delete cascade;

alter table if exists follow_ups add constraint FKanqh2lrhghex8k3dego9um3jh foreign key (lead_id) references leads;

alter table if exists messages add constraint FKt492th6wsovh1nush5yl5jj8e foreign key (conversation_id) references conversations;

alter table if exists messages add constraint FK4ui4nnwntodh6wjvck53dbk9m foreign key (sender_id) references users on delete cascade;

alter table if exists project_configs add constraint FKoeeik0i8qr27twf4ut25afxvy foreign key (project_id) references projects;

alter table if exists projects add constraint FKrdf97scpatk3kkck4svqaaksf foreign key (location_id) references locations;

ALTER TABLE projects ALTER COLUMN is_deleted SET DEFAULT FALSE;
ALTER TABLE users ALTER COLUMN token_version SET DEFAULT 0;
ALTER TABLE areas ALTER COLUMN active SET DEFAULT TRUE;
ALTER TABLE custom_cities ALTER COLUMN active SET DEFAULT TRUE;
ALTER TABLE employees ADD CONSTRAINT fk_employees_user_id FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL;
ALTER TABLE leads ADD CONSTRAINT fk_leads_assigned_user_id FOREIGN KEY (assigned_user_id) REFERENCES users(id) ON DELETE SET NULL;
ALTER TABLE leads ADD CONSTRAINT fk_leads_area_id FOREIGN KEY (area_id) REFERENCES areas(id) ON DELETE SET NULL;
ALTER TABLE users ADD CONSTRAINT fk_users_custom_city FOREIGN KEY (custom_city_id) REFERENCES custom_cities(id) ON DELETE SET NULL;
ALTER TABLE users ADD CONSTRAINT fk_users_area FOREIGN KEY (area_id) REFERENCES areas(id) ON DELETE SET NULL;
ALTER TABLE buildings ADD CONSTRAINT fk_building_project FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE;
ALTER TABLE floors ADD CONSTRAINT fk_floor_project FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE;
ALTER TABLE floors ADD CONSTRAINT fk_floor_building FOREIGN KEY (building_id) REFERENCES buildings(id) ON DELETE CASCADE;
ALTER TABLE property_units ADD CONSTRAINT fk_unit_project FOREIGN KEY (property_project_id) REFERENCES projects(id) ON DELETE CASCADE;
ALTER TABLE property_units ADD CONSTRAINT fk_unit_building FOREIGN KEY (building_id) REFERENCES buildings(id) ON DELETE CASCADE;
ALTER TABLE property_units ADD CONSTRAINT fk_unit_floor FOREIGN KEY (floor_id) REFERENCES floors(id) ON DELETE CASCADE;
ALTER TABLE unit_documents ADD CONSTRAINT fk_doc_project FOREIGN KEY (property_project_id) REFERENCES projects(id) ON DELETE CASCADE;
ALTER TABLE unit_documents ADD CONSTRAINT fk_doc_unit FOREIGN KEY (unit_id) REFERENCES property_units(id) ON DELETE CASCADE;
ALTER TABLE follow_ups ADD CONSTRAINT fk_followup_creator FOREIGN KEY (created_by_user_id) REFERENCES users(id);
ALTER TABLE follow_ups ADD CONSTRAINT fk_followup_owner FOREIGN KEY (owner_user_id) REFERENCES users(id);
CREATE UNIQUE INDEX idx_leads_email_unique ON leads(email) WHERE email IS NOT NULL;
CREATE INDEX idx_employees_user_id ON employees(user_id);
CREATE INDEX idx_leads_assigned_user_id ON leads(assigned_user_id);
CREATE INDEX idx_leads_area_id ON leads(area_id);
CREATE INDEX idx_projects_is_deleted ON projects(is_deleted);
CREATE INDEX idx_projects_deleted_at ON projects(deleted_at);
CREATE TABLE migration_warnings (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    migration VARCHAR(100) NOT NULL,
    entity VARCHAR(100) NOT NULL,
    entity_id BIGINT,
    message TEXT,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
